package com.bookstore.service; import com.bookstore.entity.*; import com.bookstore.repository.*; import com.bookstore.service.impl.OrderServiceImpl; import org.junit.jupiter.api.*; import java.math.BigDecimal; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; class OrderServiceImplTest{OrderRepository orders=mock(OrderRepository.class);CustomerRepository customers=mock(CustomerRepository.class);BookRepository books=mock(BookRepository.class);OrderServiceImpl service=new OrderServiceImpl(orders,customers,books);@Test void reducesStockAndCalculatesTotal(){Customer c=new Customer();Book b=new Book();b.setTitle("Java");b.setPrice(new BigDecimal("100"));b.setStockQuantity(5);when(customers.findById(1L)).thenReturn(Optional.of(c));when(books.findById(2L)).thenReturn(Optional.of(b));when(orders.save(any())).thenAnswer(i->i.getArgument(0));Order result=service.create(1L,List.of(2L),List.of(2));assertEquals(3,b.getStockQuantity());assertEquals(new BigDecimal("200"),result.getTotal());}}